########## packs/basics/tasks/ci-performance/task.mjs
// basics task: ci-performance — the weekly read on where this repo's CI time goes,
// and whether it has got worse.
//
// A suite's runtime degrades the way a lawn grows: never in one visible step, so
// nobody profiles it until it is bad enough to complain about, by which point the
// cause is a dozen changes back. This task takes the measurement on a cadence
// instead, from the one ledger that cannot be argued with — the Actions run
// history — and keeps a standing record of it.
//
// CONDITIONAL HANDOFF. Code-work does the measuring, which is pure code: read the
// runs, take each workflow's median over this window and the one before, compare.
// A quiet week ends there — the record is refreshed and no agent is spent. Only a
// real regression requests the agent, which then has something worth its time: a
// named workflow, a before and after, and the ci-performance-evaluation skill's
// method for finding the cause.
//
// WHY sonnet: the finding arrives already localized to a workflow and a delta, and
// the skill states the method step by step; what remains is profiling and a bounded
// fix. Ceilinged at `open-pr`, so a change to how this repo builds or tests always
// lands in front of a reviewer.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'ci-performance',
  frequency: 'weekly',
  // Movement, not standing state: CI runtime only changes when something lands, so
  // a week with no commits and no PR activity has nothing new to measure — the same
  // runs, the same medians, the same verdict as last week.
  precondition_signals: ['commits', 'prs'],
  agent_model: 'sonnet',
  expected_outcome: 'pr',
  automerge: 'anything',             // CI itself is the gate: a fix that turns anything red cannot merge, and a green one is the point (owner, 2026-08-30)
  agent_instructions: 'task.md',
  code_work: 'node worker.mjs',
  // A couple of hundred run records plus one job breakdown, against this repo's own
  // API. Seconds in practice; the bound is for a rate-limited or wedged read.
  code_work_timeout: 300,
  // Profiling a suite means running it, more than once, in both arms of an A/B.
  agent_execution_timeout: 3600,

  precondition(signals) {
    const commits = signals.commits?.count ?? 0;
    const prs = (signals.prs?.touched ?? []).length;
    if (commits === 0 && prs === 0) {
      return { run: false, reason: 'no commits and no PR activity this week — CI ran on nothing new, so its timings cannot have moved' };
    }
    return { run: true, reason: `${commits} commit(s) and ${prs} touched PR(s) this week — re-measure CI timings and compare against the previous window` };
  },
};
########## packs/chrome-extension/tasks/store-release/task.mjs
// chrome-extension task: store-release — the pack-contributed release
// trigger (per-project-scheduling DESIGN §6). STRUCTURAL Stage 2: `model: 'none'`
// means the whole decision is code and there is NO agent phase —
// the executor runs `worker.mjs` as code-work. This task ABSORBS the
// release workflow's own independent 00:30 cron: the workflow becomes push +
// workflow_dispatch only, and this task is the one place that fires its daily
// leg, so the scheduler stays the repo's only cron (DESIGN §3, decision §11.6).
//
// Self-contained (imports nothing): the whole contract is this default export.

const norm = (v) => String(v ?? '').replace(/^v/, '').trim(); // compare tags/versions modulo a leading 'v'

export default {
  id: 'store-release',
  frequency: 'daily',              // the 04:00 anchor (DESIGN §2) — replaces the workflow's own 00:30 cron
  precondition_signals: ['release', 'commits'],
  agent_model: 'none',                   // pure code — no agent (task-code-work DESIGN §4)
  expected_outcome: 'none',                 // it only TRIGGERS the gated publish workflow; publishing stays behind that workflow's own guards
  code_work: 'node worker.mjs',      // the executor runs this as code_work (cwd = this task dir) — DESIGN §3
  code_work_timeout: 120,            // the dispatch is a quick REST call; a tight bound (the await-the-run Stage 2 would widen it)

  // Detect a deployable change since the last release, entirely in code:
  //   (a) the manifest version has advanced past the latest published release
  //       (an unreleased bump — the same signal the old run_daily gate used), OR
  //   (b) a substantive default-branch commit landed in the window (a real ship).
  // Ship-path precision (the daily job's `ship_paths` filter) is NOT re-derived
  // here — .github/release.config isn't in a precondition's scope — because the
  // dispatched daily workflow does the authoritative shipped-file diff vs the
  // latest release tag and no-ops when nothing shippable moved. So the
  // precondition is the cheap pre-filter; the workflow is the exact gate.
  precondition(signals) {
    const rel = signals.release ?? {};

    // Does this repo publish at all? The pack is fingerprinted on the manifest, so
    // it is active on every extension repo, including the ones that only code one —
    // and the daily leg this task fires is a workflow such a repo does not have.
    // `shipsPipeline` is the same orchestrator-name test the release checks gate on
    // (#1057); null means the collector could not read the checkout, which is not a
    // reason to fire a release.
    if (rel.shipsPipeline !== true) {
      return { run: false, reason: 'this repo does not ship the Chrome Web Store pipeline' };
    }

    const shipped = norm(rel.manifestVersion);
    const released = norm(rel.latestTag);
    const manifestAhead = shipped !== '' && shipped !== released;
    const substantive = signals.commits?.substantiveChange === true;

    if (manifestAhead) {
      return { run: true, reason: released ? `manifest ${shipped} is ahead of released ${released}` : `manifest ${shipped}, no release yet` };
    }
    if (substantive) {
      return { run: true, reason: 'substantive default-branch change in the window — let the daily release workflow diff shipped files' };
    }
    return { run: false, reason: 'manifest matches the latest release and no substantive change in the window' };
  },
};
