1	// Task discovery for the scheduler (per-project-scheduling DESIGN §3.2). One
2	// uniform scan of every ACTIVE pack's `tasks/<name>/task.mjs`, activation-gated
3	// by the repo's `packs` declaration exactly like checks and skills. Reuses the
4	// pack registry so the same scan works across all three layouts without knowing
5	// any of them: canon packs at `packs/`, a consumer's vendored canon at
6	// `.claudinite/shared/packs/`, and local packs at `.claudinite/local/packs/`
7	// (each pack carries its own resolved `dir`).
8	//
9	// Frequency filtering is deliberately NOT done here — discover returns every
10	// active, well-formed task; the scheduler run intersects them with the current anchors
11	// (queue/anchors.mjs). Keeping the two apart keeps each pure and separately
12	// testable. A task whose task.mjs fails to import or violates the declaration
13	// contract is dropped into `errors` (fail-soft, per-task), never sinking the
14	// scan.
15	
16	import { readdirSync, existsSync } from 'node:fs';
17	import { join, relative } from 'node:path';
18	import { pathToFileURL } from 'node:url';
19	import { loadPacks, isActive } from '../../engine/pack_loader/pack-registry.mjs';
20	import { normalizeTaskDeclaration, validateTaskDeclaration } from './task-contract.mjs';
21	import { loadTaskTerms } from './task-terms.mjs';
22	import { BUILT_IN_PACK, builtInTasksRoot } from './built-in-tasks.mjs';
23	
24	// Discover every task the repo's active packs contribute. Returns
25	// `{ tasks, errors }` where each task is
26	// `{ pack, id, taskDir, taskPath, decl, terms }` — `taskPath` is the repo-relative
27	// path to the worker file's directory's task.md (the work item's first
28	// line), `decl` the validated declaration, and `terms` whatever precondition
29	// terms the task ships of its own (an empty map for most).
30	export async function discoverTasks(root, config) {
31	  const errors = [];
32	  const packs = await loadPacks({ localRoot: root });
33	  const active = packs.filter((p) => isActive(p, config));
34	
35	  // The BUILT-IN root beside the pack scan (DESIGN §16.2). The engine ships one
36	  // task of its own — the request implementer — so a marked issue is an ordinary
37	  // run rather than a special item shape. It is not a pack and declares nothing:
38	  // wherever the queue runs, it is active, which is also what stops any pack
39	  // opting itself into the fields only it may declare.
40	  const roots = [...active.map((p) => ({ id: p.id, dir: join(p.dir, 'tasks') }))];
41	  const builtIn = builtInTasksRoot(root);
42	  if (builtIn) roots.push({ id: BUILT_IN_PACK, dir: builtIn });
43	
44	  const tasks = [];
45	  for (const pack of roots) {
46	    const tasksRoot = pack.dir;
47	    if (!existsSync(tasksRoot)) continue;
48	    let names;
49	    try {
50	      names = readdirSync(tasksRoot, { withFileTypes: true })
51	        .filter((d) => d.isDirectory()).map((d) => d.name).sort();
52	    } catch (e) {
53	      errors.push({ pack: pack.id, what: `${pack.id}'s tasks/ is not a readable directory: ${e.message}`, fix: `make ${relative(root, tasksRoot)} a directory (or remove it)` });
54	      continue;
55	    }
56	    for (const name of names) {
57	      const taskDir = join(tasksRoot, name);
58	      const mjs = join(taskDir, 'task.mjs');
59	      if (!existsSync(mjs)) continue;
60	      let decl;
61	      try {
62	        // Canonical field names from here on (legacy code-work names accepted at
63	        // the door, never re-checked downstream).
64	        decl = normalizeTaskDeclaration((await import(pathToFileURL(mjs).href)).default);
65	      } catch (e) {
66	        errors.push({ pack: pack.id, task: name, what: `${relative(root, mjs)} failed to import: ${e.message}`, fix: 'fix or remove the task' });
67	        continue;
68	      }
69	      // The task's own precondition terms, loaded BEFORE validation: a
70	      // declaration naming one is well-formed only against the file that defines
71	      // it, so a terms file that will not import fails the task rather than
72	      // making its own conditions look like typos.
73	      let terms;
74	      try {
75	        terms = await loadTaskTerms(taskDir);
76	      } catch (e) {
77	        errors.push({ pack: pack.id, task: name, what: `${relative(root, join(taskDir, 'preconditions.mjs'))} failed to import: ${e.message}`, fix: 'fix or remove the task\'s precondition terms' });
78	        continue;
79	      }
80	      const problems = validateTaskDeclaration(decl, terms);
81	      if (problems.length) {
82	        errors.push({ pack: pack.id, task: name, what: `${relative(root, mjs)} is not a valid task declaration: ${problems.map((p) => p.what).join('; ')}`, fix: problems[0].fix });
83	        continue;
84	      }
85	      // A local pack's dir-name is its id (enforced by the registry); the task's
86	      // directory name should likewise match its declared id — a mismatch would
87	      // make the dispatch path and the declaration disagree.
88	      if (decl.id !== name) {
89	        errors.push({ pack: pack.id, task: name, what: `task in ${relative(root, taskDir)} declares id "${decl.id}" but its directory is "${name}"`, fix: 'rename the directory to the task id, or set the id to the directory name' });
90	        continue;
91	      }
92	      tasks.push({
93	        pack: pack.id,
94	        id: decl.id,
95	        taskDir,
96	        taskPath: `${relative(root, taskDir).split('\\').join('/')}/task.md`,
97	        decl,
98	        terms,
99	      });
100	    }
101	  }
102	  return { tasks, errors };
103	}

