1	// The signal collectors (per-project-scheduling DESIGN §3.3). Each reads a
2	// bounded, cheap slice of the repo's GitHub state (or local disk) for one signal
3	// name; `collectSignals` gathers only the union the PICKED task declared, so an
4	// hourly task never pays for a daily task's signals. Every collector takes the
5	// shared `(gh, ctx)` and returns a plain data object a precondition reads.
6	//
7	// Pure over the injected `gh` reader and a `ctx` of already-resolved facts, so
8	// the whole layer tests against a fake `gh` with no live GitHub. The ctx facts a
9	// collector cannot fetch for itself (manifest version, local-pack presence,
10	// retention) are read off the checkout by signals/context.mjs — see signals/local.mjs.
11	
12	import { SHARED_SUBDIR } from '../../../engine/pack_loader/pack-registry.mjs';
13	import { LOCAL_PACK_ROOTS } from './local.mjs';
14	import { QUEUED_LABEL, ORIGIN_AD_HOC, REQUEST_LABEL } from '../queue/work-item.mjs';
15	import { APPROVAL_RE } from '../built-in-tasks.mjs';
16	import { taskFromMessage } from '../task-trailer.mjs';
17	
18	// A default-branch commit is genuine project work unless it is bot/CI
19	// housekeeping or one of Claudinite's own automated writes — the same exclusions
20	// the fleet planner applies (kept in sync), extended with the scheduler's own
21	// `[claudinite-task]` and `[claudinite-work]` writes so neither dispatch
22	// mechanism ever self-triggers. The queue's vocabulary is excluded HERE, before
23	// any repo flips (tasks-dispatch F8): a queue-mode repo's own work items are
24	// repo activity to every precondition watching issues, so a collector that had
25	// not learned the new title would wake tasks on the queue's own churn.
26	const HOUSEKEEPING = /\[skip ci\]|(^|\n)\s*baselin(e|ing)\b|claudinite[ -](baselin|maintenance|growth|task|work)|seed default-on/i;
27	
28	// …and a THIRD exclusion the message cannot express: a commit that touched
