import re, io, sys

def strip_precondition(t, path):
    i = t.index('\n  precondition(')
    # walk back over the contiguous comment/blank block that documents it
    lines = t[:i+1].split('\n')
    k = len(lines) - 1  # index of the '' produced by trailing \n
    j = k - 1
    while j >= 0 and (lines[j].strip().startswith('//') or lines[j].strip() == ''):
        j -= 1
    start = len('\n'.join(lines[:j+1])) + 1
    end = t.rindex('\n  },\n};') + len('\n  },\n')
    return t[:start] + t[end:]

def set_preconditions(t, block, path):
    # replace the precondition_signals line (and any trailing same-line comment)
    m = re.search(r'^  precondition_signals: \[[^\]]*\],.*\n', t, re.M)
    assert m, path
    return t[:m.start()] + block + t[m.end():]

