75	      if (text === null || isReExport(text)) continue;
76	      const flag = (what, fix) => out.push(finding(rule, { file, what, fix }));
77	      const model = strField(text, 'agent_model');
78	
79	      if (!/export\s+default\s*\{/.test(text)) {
80	        flag('does not default-export a declaration object', 'export default { id, frequency, preconditions, agent_model, expected_outcome, agent_instructions }');
81	        continue;
82	      }
83	      const enumField = (key, legal) => {
