    ...REQUEST_TASK,
    decl: { ...requestTask, preconditions: ['spy'] },
    terms: new Map([['spy', {
      signals: ['request'],
      holds: (signals, { item: occurrence }) => { seen.push(occurrence); return { holds: false, reason: 'looked' }; },
    }]]),
  };"""
assert old in t; t=t.replace(old,new)
t=t.replace("""  // The third argument (§16.4) is what lets a verdict be about one target. Nothing
